INSERT INTO app_publish_preflight_result (
    tenant_id, application_id, publish_request_id, candidate_fingerprint, passed,
    blockers_json, warnings_json, trace_id, checked_by, checked_at,
    created_at, updated_at, version
) VALUES (
    #{tenantId}, #{applicationId}, #{publishRequestId}, #{candidateFingerprint}, #{passed},
    CAST(#{blockersJson} AS jsonb), CAST(#{warningsJson} AS jsonb),
    #{traceId}, #{checkedBy}, #{checkedAt}, #{createdAt}, #{updatedAt}, #{version}
)
ON CONFLICT (tenant_id, application_id, publish_request_id) DO NOTHING

mapper.select:
SELECT id, tenant_id, application_id, publish_request_id, candidate_fingerprint, passed,
       blockers_json::text AS blockers_json,
       warnings_json::text AS warnings_json,
       trace_id, checked_by, checked_at, created_at, updated_at, version
FROM app_publish_preflight_result
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND publish_request_id = #{publishRequestId}
LIMIT 1
